
from pathlib import Path
import pandas as pd
import matplotlib.pyplot as plt

BASE_DIR = Path(__file__).resolve().parent.parent
DATA_DIR = BASE_DIR / "data"
OUTPUT_DIR = BASE_DIR / "visualizations"
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

# Load cleaned data generated by clean_and_eda.py
df = pd.read_csv(DATA_DIR / "cleaned_mamaearth_data.csv")
df["order_date"] = pd.to_datetime(df["order_date"], errors="coerce")
df["payment_method"] = (
    df["payment_method"].astype(str).str.strip().str.upper()
)
df["returned"] = pd.to_numeric(df["returned"], errors="coerce").fillna(0)
df["order_value"] = pd.to_numeric(df["order_value"], errors="coerce")
df["quantity_outlier"] = (
    df["quantity_outlier"].astype(str).str.strip().str.lower() == "true"
)

# 1. Return rate by payment method
payment_returns = (
    df.groupby("payment_method")
    .agg(
        total_orders=("order_id", "count"),
        returned_orders=("returned", "sum"),
    )
)

payment_returns["return_rate_pct"] = (
    payment_returns["returned_orders"]
    / payment_returns["total_orders"] * 100
)

payment_returns = payment_returns.sort_values(
    "return_rate_pct", ascending=False
)

ax = payment_returns["return_rate_pct"].plot(
    kind="bar", figsize=(8, 5), rot=0
)

for bar in ax.patches:
    height = bar.get_height()
    ax.annotate(
        f"{height:.1f}%",
        (bar.get_x() + bar.get_width() / 2, height),
        ha="center",
        va="bottom",
        xytext=(0, 4),
        textcoords="offset points",
    )

cod_rate = payment_returns.loc["COD", "return_rate_pct"]
card_rate = payment_returns.loc["CARD", "return_rate_pct"]

plt.title(
    f"COD Returns at {cod_rate:.1f}% "
    f"vs CARD at {card_rate:.1f}%"
)
plt.xlabel("Payment Method")
plt.ylabel("Return Rate (%)")
plt.ylim(0, max(payment_returns["return_rate_pct"]) * 1.2)
plt.tight_layout()
plt.savefig(OUTPUT_DIR / "return_rate_by_payment.png", dpi=300)
plt.close()

# 2. Monthly revenue excluding quantity outliers
valid = df.loc[~df["quantity_outlier"]].copy()
valid["month"] = valid["order_date"].dt.to_period("M").astype(str)

monthly = (
    valid.groupby("month")["order_value"]
    .sum()
    .sort_index()
)

peak_month = monthly.idxmax()
peak_revenue = monthly.max()

ax = monthly.plot(
    kind="line", marker="o", figsize=(9, 5)
)

plt.title(
    f"Monthly Revenue Excluding Outliers "
    f"(Peak: {peak_month}, INR {peak_revenue:,.2f})"
)
plt.xlabel("Month")
plt.ylabel("Revenue (INR)")
plt.xticks(rotation=45)
plt.tight_layout()
plt.savefig(OUTPUT_DIR / "monthly_revenue_trend.png", dpi=300)
plt.close()

print("Visualizations generated successfully.")
print("1. visualizations/return_rate_by_payment.png")
print("2. visualizations/monthly_revenue_trend.png")
print("\nReturn rate by payment method:")
print(payment_returns[["total_orders", "return_rate_pct"]].round(1))
print(f"\nPeak month after excluding outliers: {peak_month}")
print(f"Peak revenue: INR {peak_revenue:,.2f}")
